from typing import List
import heapq


class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        INF = float('inf')
        best = [INF] * n
        best[0] = 0
        heap = [(0, 0)]
        visited = 0
        answer = 0

        while heap:
            d, u = heapq.heappop(heap)
            if d > best[u]:
                continue
            visited += 1
            if d > answer:
                answer = d
            for v, w in rev[u]:
                nd = w if w > d else d
                if nd < best[v]:
                    best[v] = nd
                    heapq.heappush(heap, (nd, v))

        if visited < n:
            return -1
        return answer if answer > 0 else -1 if n > 1 and not edges else answer
